const express = require('express');
const multer = require('multer');
const unzipper = require('unzipper');
const path = require('path');
const fs = require('fs');

const app = express();
const upload = multer({ dest: '/tmp/uploads/' });

const EXTRACT_DIR = '/app/data/extracted';

// Ensure extraction directory exists
if (!fs.existsSync(EXTRACT_DIR)) {
  fs.mkdirSync(EXTRACT_DIR, { recursive: true });
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// File upload and extraction endpoint
app.post('/api/v1/documents/upload', upload.single('archive'), async (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  const allowedMimes = ['application/zip', 'application/x-zip-compressed'];
  if (!allowedMimes.includes(req.file.mimetype)) {
    fs.unlinkSync(req.file.path);
    return res.status(415).json({ error: 'Only ZIP files are accepted' });
  }

  const extractedFiles = [];
  const sessionDir = path.join(EXTRACT_DIR, req.file.filename);
  fs.mkdirSync(sessionDir, { recursive: true });

  try {
    const directory = await unzipper.Open.file(req.file.path);

    for (const entry of directory.files) {
      // Skip directories
      if (entry.type === 'Directory') continue;

      // Construct output path - NOTE: entry.path is used directly
      // This allows path traversal via entries like "../../etc/cron.d/backdoor"
      const outputPath = path.join(sessionDir, entry.path);

      // Create parent directories
      const parentDir = path.dirname(outputPath);
      if (!fs.existsSync(parentDir)) {
        fs.mkdirSync(parentDir, { recursive: true });
      }

      // Extract file content
      const content = await entry.buffer();
      fs.writeFileSync(outputPath, content);
      extractedFiles.push(entry.path);
    }

    // Cleanup uploaded zip
    fs.unlinkSync(req.file.path);

    res.json({
      success: true,
      extractionId: req.file.filename,
      files: extractedFiles,
      count: extractedFiles.length
    });
  } catch (err) {
    console.error('Extraction failed:', err.message);
    fs.unlinkSync(req.file.path);
    res.status(500).json({ error: 'Failed to process archive' });
  }
});

// List extracted documents
app.get('/api/v1/documents/:extractionId', (req, res) => {
  const dir = path.join(EXTRACT_DIR, req.params.extractionId);
  if (!fs.existsSync(dir)) {
    return res.status(404).json({ error: 'Extraction not found' });
  }

  const files = fs.readdirSync(dir, { recursive: true });
  res.json({ files });
});

// Download specific extracted file
app.get('/api/v1/documents/:extractionId/*', (req, res) => {
  const filePath = path.join(EXTRACT_DIR, req.params.extractionId, req.params[0]);
  if (!fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'File not found' });
  }
  res.sendFile(filePath);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Document service listening on port ${PORT}`);
});
